"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["28501"],{86179(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.exigencia_por_opcao_invalida","status":422,"titulo":"O documento s\xf3 se multiplica pelas op\xe7\xf5es de fato categ\xf3rico cujas op\xe7\xf5es o processo declara"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.exigencia_por_opcao_invalida","requisitos":["UNI-REQ-0170"],"oQueAconteceu":["Um documento exigido do conte\xfado do modelo, em `documentosExigidos`, traz `porOpcao` com um `fatoCodigo` que existe no cat\xe1logo de fatos, mas n\xe3o \xe9 de dom\xednio `OPCAO` com fonte de valores `OPCOES_DO_PROCESSO`. A exig\xeancia por op\xe7\xe3o pede o documento uma vez por op\xe7\xe3o que o processo oferece para o fato, como uma exig\xeancia por condi\xe7\xe3o de atendimento (UNI-REQ-0170). Como o modelo n\xe3o enumera as op\xe7\xf5es, que s\xf3 existem no processo, s\xf3 serve para isso o fato cujas op\xe7\xf5es o processo declara.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.documentosExigidos[i].porOpcao.fatoCodigo`, e a mensagem cita o c\xf3digo do fato. Um fato que n\xe3o existe no cat\xe1logo \xe9 recusado por outro c\xf3digo, o de [fato desconhecido](/erros/uniplus.item_formulario.fato_desconhecido). A cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) e a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) conferem a mesma regra, e as demais recusas do conte\xfado v\xeam na mesma resposta. Nada \xe9 gravado.","O \xedndice `i` do `field` \xe9 a posi\xe7\xe3o do documento em `documentosExigidos` no corpo enviado, mesmo quando um documento anterior foi descartado na leitura por [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada): a recusa aponta o documento que precisa de corre\xe7\xe3o, e n\xe3o o que est\xe1 certo.","Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Escolha em `porOpcao.fatoCodigo` um fato do cat\xe1logo de dom\xednio categ\xf3rico cujas op\xe7\xf5es o processo declara, ou retire `porOpcao` e exija o documento uma \xfanica vez. Consulte os fatos em `GET /api/configuracao/fatos-candidato`."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);